import { describe, it } from "vitest";

describe("quote: item base premiums", () => {
  it.todo("empty item list -- premium 5 G (only the processing fee)");
  it.todo("sword -- 100 base + 10 first insurance + 5 fee = 115 G");
  it.todo("amulet -- 60 base + 6 first insurance + 5 fee = 71 G");
  it.todo("staff -- 80 base + 8 first insurance + 5 fee = 93 G");
  it.todo("potion -- 40 base + 4 first insurance + 5 fee = 49 G");
});

describe("quote: components and building blocks", () => {
  it.todo("2 runes -- 50 base + 5 + 5 = 60 G");
  it.todo("2 moonstones -- 50 base + 5 + 5 = 60 G (moonstone is a component too)");
  it.todo("3 runes -- block applies: 60 base + 6 + 5 = 71 G");
  it.todo("3 moonstones -- block applies: 60 base + 6 + 5 = 71 G");
  it.todo("4 runes -- no block (exactly 3 required): 100 base + 10 + 5 = 115 G");
  it.todo("7 runes -- 175 base, premium 197.5 rounded up to 198 G (rounding in MHPCO's favor)");
  it.todo("2 runes + 1 moonstone -- 'alike' means same type: 75 base + 7.5 + 5 = 87.5 rounded up to 88 G");
  it.todo("3 runes + 3 moonstones -- two separate blocks: 120 base + 12 + 5 = 137 G");
});

describe("quote: item-specific modifiers", () => {
  it.todo("cursed sword, enchantment 3, newcomer -- 100 + 50 curse + 10 first + 5 = 165 G");
  it.todo("sword enchantment 4, not cursed -- no high-enchantment surcharge: 115 G");
  it.todo("sword enchantment 4, cursed -- curse only: 165 G");
  it.todo("sword enchantment 5 -- high-enchantment surcharge applies: 100 + 30 + 10 + 5 = 145 G");
  it.todo("cursed sword enchantment 5 -- both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("cursed sword + plain amulet -- curse applies to the sword only: 160 base + 50 + 16 first + 5 = 231 G");
  it.todo("sword enchantment 5 + plain amulet -- 30 % of sword base only: 160 + 30 + 16 + 5 = 211 G");
});

describe("quote: customer modifiers", () => {
  it.todo("customer with exactly 2 years -- loyalty discount applies: 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year -- no loyalty discount: 115 G");
  it.todo("second quote of a newcomer -- follow-up discount: 100 + 10 - 15 + 5 = 100 G");
  it.todo("long-standing customer's second quote, cursed sword enchantment 7 -- 160 G");
  it.todo("a claim between two quotes does not hide the follow-up: quote, claim, quote -- second quote has follow-up discount");
});

describe("quote: rejection", () => {
  it.todo("unknown item type 'broomstick' -- quote is rejected with an error");
});

describe("claim: standard reimbursement and caps", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 -- payout 400, remaining cap 1600");
  it.todo("rune, damage 200 -- payout 100 (no special clause), remaining cap 400");
  it.todo("damage below the deductible -- payout 0 (payout never negative), cap untouched");
  it.todo("amulet, damage 200 -- payout 100, remaining cap 1100 (insured 600, cap 1200)");
  it.todo("staff, damage 200 -- payout 100, remaining cap 1500 (insured 800, cap 1600)");
  it.todo("potion, damage 200 -- payout 100, remaining cap 700 (insured 400, cap 800)");
  it.todo("moonstone, damage 200 -- payout 100, remaining cap 400 (insured 250, cap 500)");
});

describe("claim: enchantment and dragon material", () => {
  it.todo("dragon sword enchantment 8, damage 1000 -- payout 400");
  it.todo("dragon sword enchantment 9, damage 1000 -- payout 400 (50 % rule wins)");
  it.todo("dragon sword enchantment 5, damage 800 -- payout 700 (full reimbursement)");
  it.todo("steel sword enchantment 9, damage 1000 -- payout 400");
  it.todo("steel sword enchantment 7, damage 1000 -- payout 900 (below the 8 threshold)");
  it.todo("payout calculation yielding 350.5 -- payout 350 (rounded down)");
});

describe("claim: deductible per damaged item and multiple items", () => {
  it.todo("sword 500 + amulet 300 damaged -- payout 600 (deductible once per item), remaining cap 2600");
  it.todo("two swords insured and both damaged by 500 -- payout 800, remaining cap 3200 (cap 4000)");
  it.todo("two swords, damages taken in policy order: steel 1000 + dragon enchantment 9 1000 -- payout 1300");
  it.todo("cursed sword -- cap stays 2000, premium modifiers do not raise it: damage 500 -> remaining cap 1600");
  it.todo("sword + 3 runes -- insurance sum 1750, cap 3500: damage 500 -> remaining cap 3100");
});

describe("claim: cap exhaustion", () => {
  it.todo("two successive claims of 1500 on a sword -- payouts 1400 then 600, remaining cap 600 then 0");
});

describe("claim: rejection", () => {
  it.todo("two sword damages but only one sword insured -- claim is rejected with an error");
  it.todo("amulet damaged while only a sword is insured -- claim is rejected with an error");
  it.todo("damage entry with unknown item type -- claim is rejected with an error");
  it.todo("damage amount -200 -- claim is rejected with an error");
});

