const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

export function basePremiumOf(itemType: string): number {
  return BASE_PREMIUMS[itemType];
}

function countByType(itemTypes: string[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const itemType of itemTypes) {
    counts.set(itemType, (counts.get(itemType) ?? 0) + 1);
  }
  return counts;
}

export function policyBasePremium(itemTypes: string[]): number {
  let total = 0;
  for (const [itemType, count] of countByType(itemTypes)) {
    const isBlock = COMPONENT_TYPES.has(itemType) && count === COMPONENT_BLOCK_SIZE;
    total += isBlock ? COMPONENT_BLOCK_PREMIUM : count * basePremiumOf(itemType);
  }
  return total;
}

