import { basePremiumOf, policyBasePremium } from "./price-list.js";

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResults {
  results: unknown[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_PERCENT = 10;
const CURSED_PERCENT = 50;
const PERCENT = 100;

function itemSurchargePercent(item: QuoteItem): number {
  return item.cursed ? CURSED_PERCENT : 0;
}

function quotePremium(step: QuoteStep): number {
  const policyBase = policyBasePremium(step.items.map((item) => item.type));
  const policyPercent = PERCENT + FIRST_INSURANCE_PERCENT;
  const itemSurcharges = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item.type) * itemSurchargePercent(item),
    0,
  );
  return Math.ceil((policyBase * policyPercent + itemSurcharges) / PERCENT) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): ScenarioResults {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step) })) };
}

