import { type Customer, type QuoteItem, quotePremium } from "./premium.js";

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ScenarioResults {
  results: unknown[];
}

export function runScenario(scenario: Scenario): ScenarioResults {
  let quotesSoFar = 0;
  const results = scenario.steps.map((step) => {
    if (step.op === "claim") {
      return { payout: 0, remainingCap: 0 };
    }
    const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
    quotesSoFar += 1;
    return { premium };
  });
  return { results };
}

