import { type Damage, settleClaim } from "./claim.js";
import { type Customer, type QuoteItem, quotePremium } from "./premium.js";

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ScenarioResults {
  results: unknown[];
}

export function runScenario(scenario: Scenario): ScenarioResults {
  const policies = new Map<number, QuoteItem[]>();
  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return settleClaim(policies.get(step.policy) ?? [], step.incident.damages);
    }
    const premium = quotePremium(step.items, scenario.customer, policies.size > 0);
    policies.set(index, step.items);
    return { premium };
  });
  return { results };
}

