import { insuranceValueOf } from "./price-list.js";
import type { QuoteItem } from "./premium.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;
const HIGH_ENCHANTMENT_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;

function insuranceSum(policyItems: QuoteItem[]): number {
  return policyItems.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
}

function reimbursedAmount(item: QuoteItem | undefined, damage: Damage): number {
  const highlyEnchanted = (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
  return highlyEnchanted ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT : damage.amount;
}

function payoutForDamage(item: QuoteItem | undefined, damage: Damage): number {
  return Math.max(0, reimbursedAmount(item, damage) - DEDUCTIBLE);
}

export function settleClaim(policyItems: QuoteItem[], damages: Damage[]): ClaimSettlement {
  const payout = damages.reduce((sum, damage) => {
    const damagedItem = policyItems.find((item) => item.type === damage.itemType);
    return sum + payoutForDamage(damagedItem, damage);
  }, 0);
  return { payout, remainingCap: CAP_MULTIPLE * insuranceSum(policyItems) - payout };
}

