import type { QuoteItem } from "./premium.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;
const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
