  return isReimbursedAtHalf(item) ? damage.amount * HALF_REIMBURSEMENT : damage.amount;
}

function payoutForDamage(item: QuoteItem | undefined, damage: Damage): number {
  return Math.max(0, reimbursedAmount(item, damage) - DEDUCTIBLE);
}

export function settleClaim(policyItems: QuoteItem[], damages: Damage[]): ClaimSettlement {
  const unroundedPayout = damages.reduce((sum, damage) => {
    const damagedItem = policyItems.find((item) => item.type === damage.itemType);
    return sum + payoutForDamage(damagedItem, damage);
