import { type Damage, policyCap, settleClaim } from "./claim.js";
import { type Customer, type QuoteItem, quotePremium } from "./premium.js";

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ScenarioResults {
  results: unknown[];
}

interface Policy {
  items: QuoteItem[];
  remainingCap: number;
}

export function runScenario(scenario: Scenario): ScenarioResults {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy) as Policy;
      const settlement = settleClaim(policy.items, step.incident.damages, policy.remainingCap);
      policy.remainingCap = settlement.remainingCap;
      return settlement;
    }
    const premium = quotePremium(step.items, scenario.customer, policies.size > 0);
    policies.set(index, { items: step.items, remainingCap: policyCap(step.items) });
    return { premium };
  });
  return { results };
}

