import { insuranceValueOf } from "./price-list.js";
import type { QuoteItem } from "./premium.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;
const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
const HALF_REIMBURSEMENT = 0.5;

function insuranceSum(policyItems: QuoteItem[]): number {
  return policyItems.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
}

function isReimbursedAtHalf(item: QuoteItem | undefined): boolean {
  return (item?.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT;
}

function reimbursedAmount(item: QuoteItem | undefined, damage: Damage): number {
  return isReimbursedAtHalf(item) ? damage.amount * HALF_REIMBURSEMENT : damage.amount;
}

function payoutForDamage(item: QuoteItem | undefined, damage: Damage): number {
  return Math.max(0, reimbursedAmount(item, damage) - DEDUCTIBLE);
}

function takeNextInsuredItem(undamagedItems: QuoteItem[], itemType: string): QuoteItem {
  const position = undamagedItems.findIndex((item) => item.type === itemType);
  const [insuredItem] = undamagedItems.splice(position, 1);
  return insuredItem;
}

function totalReimbursement(policyItems: QuoteItem[], damages: Damage[]): number {
  const undamagedItems = [...policyItems];
  return damages.reduce((sum, damage) => {
    const damagedItem = takeNextInsuredItem(undamagedItems, damage.itemType);
    return sum + payoutForDamage(damagedItem, damage);
  }, 0);
}

export function policyCap(policyItems: QuoteItem[]): number {
  return CAP_MULTIPLE * insuranceSum(policyItems);
}

export function settleClaim(policyItems: QuoteItem[], damages: Damage[], remainingCap: number): ClaimSettlement {
  const payout = Math.min(Math.floor(totalReimbursement(policyItems, damages)), remainingCap);
  return { payout, remainingCap: remainingCap - payout };
}

